package org.circus.core;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.InflaterInputStream;

/** Actual C stream-transform leaves against complete original instruction
 *programs. Uses the one live PE backing; no hardware/device/EXE execution. */
public final class Pc1DirectSoundTransformAudit {
    private static int checks;
    private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    private static int n(Object value){return(int)((Number)value).longValue();}
    private static int field(Map<?,?> row,String key,int fallback){return row.containsKey(key)?n(row.get(key)):fallback;}
    private static byte[] data(ByteBuffer raw){byte[] out=new byte[raw.capacity()];for(int k=0;k<out.length;k++)out[k]=raw.get(k);return out;}
    private static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];for(int c;(c=in.read(b))!=-1;)out.write(b,0,c);return out.toByteArray();}
    private static Pc1Audio.Catalog empty(){return new Pc1Audio.Catalog(){public int musicCount(){return 0;}public int soundCount(){return 0;}public Pc1Audio.Entry music(int n)throws IOException{throw new IOException("unused");}public Pc1Audio.Entry sound(int n)throws IOException{throw new IOException("unused");}};}
    private static Pc1NativeMemory memory()throws IOException{final byte[] settings=new byte[Pc1NativeSettings.SIZE];return new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at){return settings[at]&255;}public void write(int at,int value){settings[at]=(byte)value;}});}
    private static final String VECTORS="";
    public static void main(String[] args)throws Exception{
        if(args.length!=1)throw new IOException("Expected immutable audio DLL");String json;try(InputStream in=new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(VECTORS)))){json=new String(readAll(in),StandardCharsets.UTF_8);}Map<?,?> report=(Map<?,?>)DataJson.parse(json);List<?> rows=(List<?>)report.get("cases");check(rows.size()==8,"All full native transform programs embedded");
        for(Object value:rows){Map<?,?> row=(Map<?,?>)value,c=(Map<?,?>)row.get("case");String id=c.get("id").toString();try(Pc1DirectSound backend=Pc1DirectSound.deferred(Paths.get(args[0]),null)){
            Pc1Audio audio=new Pc1Audio(backend,empty());Pc1NativeMemory bus=memory();audio.bindNativeMemory(bus);backend.bindNativeMemory(bus);Pc1EffectPeMemory pe=new Pc1EffectPeMemory(bus);backend.bindEffectPeMemory(pe);ByteBuffer globals=backend.borrowDecoderRegion(0x455574),ring=backend.borrowDecoderRegion(0xbc5f80),pcm=backend.borrowDecoderRegion(0xbc1da4),encodedAlias=backend.borrowDecoderRegion(0xbc3da4);
            if(Boolean.TRUE.equals(c.get("dirty")))for(int k=0;k<globals.capacity();k++)globals.put(k,(byte)(k*37+9));globals.putInt(0x48d578-0x455574,field(c,"ready",0));backend.initializeDecoderTables();int seed=n(c.get("seed"));for(int k=0;k<65536;k++)ring.put(k,Boolean.TRUE.equals(c.get("zero"))?0:(byte)(k*29+(k>>>3)*7+seed));for(int k=0;k<pcm.capacity();k++)pcm.put(k,(byte)(k*11+seed));
            if(c.containsKey("patches"))for(Object patch:(List<?>)c.get("patches")){List<?> pair=(List<?>)patch;audio.writeNativeInt(n(pair.get(0)),n(pair.get(1)));}int extra=n(c.get("extra"));backend.selectDspCoefficientsForAudit(extra);for(int block=0;block<field(c,"blocks",1);block++)backend.transformDspBlockForAudit(block*8128,extra);
            if(!Binary.sha256(data(globals)).equals(row.get("globals_sha256"))){Path debug=Paths.get("build/native-rewrite/pc1-audio-alias-stage28/dsp-transform-actual-images");Files.createDirectories(debug);Files.write(debug.resolve(id+".globals.bin"),data(globals));Files.write(debug.resolve(id+".pcm.bin"),data(pcm));System.out.println("PE expected="+row.get("pe_sha256")+" actual="+Binary.sha256(data(pe.borrowedDirectView(0x42ab1c,0x42fca8-0x42ab1c))));}
            check(Binary.sha256(data(globals)).equals(row.get("globals_sha256")),"All229384 native spectrum/FFT/LUT/stale bytes "+id);check(Binary.sha256(data(ring)).equals(row.get("lz_sha256")),"Native cursor and full ring retain exact bits "+id);check(Binary.sha256(data(pcm)).equals(row.get("pcm_sha256")),"Full16KiB PCM including overlap/stale tail "+id);check(Binary.sha256(data(pe.borrowedDirectView(0x42ab1c,0x42fca8-0x42ab1c))).equals(row.get("pe_sha256")),"Coefficients/COS remain same live PE owner "+id);check(ring.getInt(0x14028)==n(row.get("read_cursor")),"Native ring read cursor "+id);check(Arrays.equals(data(encodedAlias),Arrays.copyOfRange(data(pcm),0x2000,0x4000)),"BC3DA4 is output scratch second-half alias, never a second live array "+id);check(audio.pcmReadyRaw()==0&&!backend.pcmInitialized(),"DSP leaves never invent a device "+id);
        }}
        System.out.println("Pc1DirectSoundTransformAudit PASS "+checks+"; full actual C kernel bytes versus original machine programs; no device/window/EXE");
    }
}
